// corner pots belong to the atrium part (P4); this part only adds the reception furniture into the air box.
//
// Design: the pool is the focus, so two marble benches (quartz stairs as seats) stand on the west and east sides of
// the coping, facing it. Every path stays clear: the fauces-to-tablinum axis along z19..21, the strips x10..12 and
// x22..25 down the sides, and the cells in front of the cubicula doorways (x10 at z12 and z18).
import { QUARTZ_STAIRS } from "./../vocab.mjs";

/** A marble bench: quartz_stairs on y2, facing the pool (the stair's open side is the seat side). */
function bench(g, x, z, facing) {
  g.set(x, 2, z, QUARTZ_STAIRS, { facing, half: "bottom", shape: "straight", waterlogged: "false" });
}

export function build(g) {
  // West bench, facing east towards the pool (x14..21 coping lies east of x13).
  bench(g, 13, 15, "east");
  bench(g, 13, 16, "east");
  // East bench, facing west towards the pool (coping ends at x21, so x22 is the seat row).
  bench(g, 22, 15, "west");
  bench(g, 22, 16, "west");
}

